local ECSComponent = import("Frame.ECS.ECSComponent")

local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule

---@class DreamlandComponent
local DreamlandComponent = Class("DreamlandComponent",ECSComponent)

function DreamlandComponent:__init()
    self.name = "DreamlandComponent"
    self._questInfo = {}             -- 后端 OverseaBoxQuest/home 数据:  Dic { k:questId; v:"home.data.boxQuestInfo[i]" }

end

function DreamlandComponent:__delete()
    self._questInfo = {}

end

function DreamlandComponent:GetQuestInfo()
    return self._questInfo
end

--入口
function DreamlandComponent:OverseaBoxQuestHomeReq(cb)
    GameUtils.Request(Interfaces.OverseaBoxQuestHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        self._questInfo = {}
        local t = jsonData.boxQuestInfo
        for k, v in pairs(t) do
            self._questInfo[checkString(v.questId)] = v
        end

        if cb then 
            cb()
        end
    end)
end


-- params: { questId, piece, isPassed, taskNum } 
function DreamlandComponent:OverseaBoxQuestGradeReq( params, cb)

    if type(params)~="table" or isNull(params.questId) or isNull(params.piece) or isNull(params.isPassed) or isNull(params.taskNum) then 
        printError("koko 白塔后端 Grade 函数参数异常")
        return
    end

    local piece = checkTable(params.piece)
    local pieceStrs = ""
    for k, v in pairs(piece) do
        if k == 1 then
            pieceStrs = pieceStrs..v
        else
            pieceStrs = pieceStrs..","..v
        end
    end

    print( "koko pieceStrs = " .. tostring(pieceStrs) )

    GameUtils.Request(Interfaces.OverseaBoxQuestGrade, {questId = params.questId, piece = pieceStrs, isPassed = params.isPassed, taskNum = params.taskNum }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        GoodsUtils.DrawRewards(jsonData.rewards, true)

        if cb then 
            cb(jsonData.rewards, piece)
        end
    end)
end

return DreamlandComponent